// Assume features(w) returns a temporary std::vector<bool>
std::vector<bool> features(const Widget& w);
Widget w;

// Solution: Use the explicitly typed initializer idiom.
// 1. features(w)[5] returns a std::vector<bool>::reference proxy.
// 2. static_cast<bool> converts the proxy to a bool immediately.
// 3. auto deduces the type of the variable as bool.
auto highPriority = static_cast<bool>(features(w)[5]);

// Matrix example
Matrix m1, m2, m3, m4;

// Solution: Force the evaluation of the expression template.
// The chained additions return a proxy object.
// The cast forces the proxy to evaluate into a new Matrix object.
// auto then deduces the type of sum as Matrix.
auto sum = static_cast<Matrix>(m1 + m2 + m3 + m4);
